# pip install "mcp[cli]"   (official Python SDK)
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("orders")

@mcp.tool()
def get_order_status(order_id: str) -> dict:
    """Status and ETA of one order. Use when the user asks where an order is."""
    # The docstring and type hints become the tool description and JSON schema:
    # write them for the model, it reads nothing else.
    order = orders_db.get(order_id)       # read-only access: least privilege
    return {"status": order.status, "eta": order.eta.isoformat()}

@mcp.resource("orders://{order_id}/invoice")
def invoice(order_id: str) -> str:
    """Invoice as text. The host app decides when to attach it."""
    return render_invoice(order_id)

@mcp.prompt()
def refund_review(order_id: str) -> str:
    """A template the user picks from a menu."""
    return f"Review order {order_id} against the refund policy and propose one action."

if __name__ == "__main__":
    mcp.run()  # stdio for local hosts; mcp.run(transport="streamable-http") for remote

